function C.weeklyPiece(weekId)
    local n = #C.items
    if n == 0 then
        return nil
    end
    weekId = weekId or tonumber(os.date('!%Y%W'))
    return C.items[(((weekId or 0) * 37) % n) + 1]
end

return C
